-- 邮箱认证：公共四表及初始化互斥行，保留旧字段和索引。
CREATE TABLE `user` (`id` int AUTO_INCREMENT,`name` varchar(255) NOT NULL,`email` varchar(255) NOT NULL,`email_verified` boolean NOT NULL DEFAULT false,`image` text,`role` varchar(255),`banned` boolean DEFAULT false,`ban_reason` text,`ban_expires` datetime,`created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY (`id`),UNIQUE INDEX `user_email_unique` (`email`),INDEX `user_role_idx` (`role`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `session` (`id` int AUTO_INCREMENT,`expires_at` datetime NOT NULL,`token` varchar(255) NOT NULL,`ip_address` varchar(255),`user_agent` text,`user_id` int NOT NULL,`impersonated_by` varchar(255),`created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY (`id`),UNIQUE INDEX `session_token_unique` (`token`),INDEX `session_user_id_idx` (`user_id`),CONSTRAINT `session_user_id_user_id_fk` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `account` (`id` int AUTO_INCREMENT,`account_id` varchar(255) NOT NULL,`provider_id` varchar(255) NOT NULL,`user_id` int NOT NULL,`access_token` text,`refresh_token` text,`id_token` text,`access_token_expires_at` datetime,`refresh_token_expires_at` datetime,`scope` text,`password` text,`created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY (`id`),UNIQUE INDEX `account_provider_account_unique` (`provider_id`,`account_id`),INDEX `account_user_id_idx` (`user_id`),CONSTRAINT `account_user_id_user_id_fk` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `verification` (`id` int AUTO_INCREMENT,`identifier` varchar(255) NOT NULL,`value` text NOT NULL,`expires_at` datetime NOT NULL,`created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY (`id`),INDEX `verification_identifier_idx` (`identifier`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `auth_bootstrap` (`id` int,`revision` int NOT NULL DEFAULT 0,PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `auth_bootstrap` (`id`, `revision`) VALUES (1, 0);
